WITH turn_uses AS (SELECT tu.id, tu.wire_tool_use_id, tu.tool_name, tu.input, tu.ord, tu.request_id, tu.operation FROM tools.uses tu JOIN requests.requests r ON r.id = tu.request_id WHERE r.operator_turn_id = 17371 AND tu.session_id = 1173418 AND tu.request_id <= 447654) SELECT u.wire_tool_use_id AS tool_id, u.tool_name, octet_length(u.input::text)::int AS input_bytes, u.ord, u.request_id, (res.tool_use_id IS NOT NULL) AS has_result, res.is_error AS result_is_error, res.content_bytes AS result_content_bytes, u.operation FROM turn_uses u LEFT JOIN tools.results res ON res.tool_use_id = u.id AND res.created_at <= '2026-09-24 08:22:50.453555+00'::timestamptz ORDER BY u.request_id ASC, u.ord ASC
